-- IA Welcome to Moscow v4 — reference DDL, PostgreSQL 16. Run migrations in staging first.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, timezone text NOT NULL DEFAULT 'Europe/Moscow');
CREATE TABLE guests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, preferred_name text, language text NOT NULL DEFAULT 'ru', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, guest_id uuid NOT NULL, channel text NOT NULL, provider_subject_hash text NOT NULL, encrypted_contact bytea, verified_at timestamptz, FOREIGN KEY(tenant_id,guest_id) REFERENCES guests(tenant_id,id), UNIQUE(tenant_id,channel,provider_subject_hash));
CREATE TABLE consents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, guest_id uuid NOT NULL, purpose text NOT NULL CHECK(purpose IN ('SERVICE','MARKETING','MEMORY','CALL_RECORDING')), channel text NOT NULL, status text NOT NULL CHECK(status IN ('GRANTED','REVOKED','UNKNOWN')), evidence_ref text NOT NULL, policy_version text NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,guest_id) REFERENCES guests(tenant_id,id));
CREATE INDEX consent_lookup ON consents(tenant_id,guest_id,purpose,channel,recorded_at DESC);
CREATE TABLE preferences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, guest_id uuid NOT NULL, key text NOT NULL, value jsonb NOT NULL, source_message_id uuid, consent_id uuid, updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,guest_id) REFERENCES guests(tenant_id,id), UNIQUE(tenant_id,guest_id,key));
CREATE TABLE apartments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, title text NOT NULL, public_address text NOT NULL, district text, metro text, rooms integer CHECK(rooms>=0), capacity integer CHECK(capacity>0), beds jsonb NOT NULL DEFAULT '[]', amenities jsonb NOT NULL DEFAULT '[]', photos jsonb NOT NULL DEFAULT '[]', source text NOT NULL, observed_at timestamptz NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(tenant_id,id));
CREATE TABLE external_mappings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, provider text NOT NULL, entity_type text NOT NULL, external_id text NOT NULL, internal_id uuid NOT NULL, UNIQUE(tenant_id,provider,entity_type,external_id));
CREATE TABLE availability_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, apartment_id uuid NOT NULL, check_in date NOT NULL, check_out date NOT NULL CHECK(check_out>check_in), status text NOT NULL CHECK(status IN ('AVAILABLE','UNAVAILABLE','UNKNOWN')), inventory_version text NOT NULL, source text NOT NULL, observed_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,apartment_id) REFERENCES apartments(tenant_id,id));
CREATE TABLE quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, apartment_id uuid NOT NULL, guest_id uuid, check_in date NOT NULL, check_out date NOT NULL CHECK(check_out>check_in), adults integer NOT NULL CHECK(adults>0), children integer NOT NULL CHECK(children>=0), currency char(3) NOT NULL, stay_total_minor bigint NOT NULL CHECK(stay_total_minor>=0), deposit_minor bigint NOT NULL CHECK(deposit_minor>=0), due_now_minor bigint NOT NULL CHECK(due_now_minor>=0), due_later_minor bigint NOT NULL CHECK(due_later_minor>=0), line_items jsonb NOT NULL, terms_version text NOT NULL, cancellation_version text NOT NULL, inventory_version text NOT NULL, source text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,apartment_id) REFERENCES apartments(tenant_id,id), FOREIGN KEY(tenant_id,guest_id) REFERENCES guests(tenant_id,id), CHECK(due_now_minor+due_later_minor=stay_total_minor), UNIQUE(tenant_id,id));
CREATE TABLE bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, apartment_id uuid NOT NULL, guest_id uuid NOT NULL, quote_id uuid, check_in date NOT NULL, check_out date NOT NULL CHECK(check_out>check_in), adults integer NOT NULL CHECK(adults>0), children integer NOT NULL DEFAULT 0 CHECK(children>=0), status text NOT NULL CHECK(status IN ('REQUESTED','PENDING_PROVIDER','CONFIRMED','CANCEL_PENDING','CANCELLED','EXPIRED','REJECTED','DELETED')), payment_status text NOT NULL DEFAULT 'UNPAID' CHECK(payment_status IN ('UNPAID','PENDING','PARTIALLY_PAID','PAID','REFUND_PENDING','PARTIALLY_REFUNDED','REFUNDED','DISPUTED')), stay_status text NOT NULL DEFAULT 'NOT_ARRIVED' CHECK(stay_status IN ('NOT_ARRIVED','CHECKED_IN','CHECKED_OUT','NO_SHOW')), version integer NOT NULL DEFAULT 1 CHECK(version>0), provider text NOT NULL, external_id text, provider_updated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,apartment_id) REFERENCES apartments(tenant_id,id), FOREIGN KEY(tenant_id,guest_id) REFERENCES guests(tenant_id,id), FOREIGN KEY(tenant_id,quote_id) REFERENCES quotes(tenant_id,id), UNIQUE(tenant_id,provider,external_id), UNIQUE(tenant_id,id));
CREATE INDEX bookings_dates ON bookings(tenant_id,apartment_id,check_in,check_out);
-- Canonical local allocation ledger only. Imported provider conflicts go to incidents,
-- never silently discarded because of this exclusion. Does not lock inventory in RC.
CREATE TABLE inventory_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, apartment_id uuid NOT NULL, booking_id uuid NOT NULL, stay daterange NOT NULL, active boolean NOT NULL DEFAULT true, FOREIGN KEY(tenant_id,apartment_id) REFERENCES apartments(tenant_id,id), FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id), EXCLUDE USING gist (tenant_id WITH =, apartment_id WITH =, stay WITH &&) WHERE(active));
CREATE TABLE booking_state_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, booking_id uuid NOT NULL, dimension text NOT NULL CHECK(dimension IN ('BOOKING','PAYMENT','STAY')), from_state text, to_state text NOT NULL, reason_code text NOT NULL, source_event_id uuid, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id));
CREATE TABLE confirmations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, actor_id uuid NOT NULL, conversation_id uuid NOT NULL, action text NOT NULL, payload_hash text NOT NULL, display_snapshot jsonb NOT NULL, status text NOT NULL CHECK(status IN ('PENDING','CONFIRMED','EXPIRED','CONSUMED')), evidence_message_id uuid, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE operations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, actor_id uuid NOT NULL, tool_name text NOT NULL, idempotency_key text NOT NULL, payload_hash text NOT NULL, status text NOT NULL CHECK(status IN ('PENDING','SUCCEEDED','FAILED','UNKNOWN')), provider_operation_id text, result jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,actor_id,tool_name,idempotency_key));
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, booking_id uuid NOT NULL, provider text NOT NULL, external_id text NOT NULL, purpose text NOT NULL CHECK(purpose IN ('STAY','DEPOSIT')), amount_minor bigint NOT NULL CHECK(amount_minor>=0), currency char(3) NOT NULL, status text NOT NULL, verified_at timestamptz, FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id), UNIQUE(tenant_id,provider,external_id), UNIQUE(tenant_id,id));
CREATE TABLE refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, payment_id uuid NOT NULL, amount_minor bigint NOT NULL CHECK(amount_minor>0), status text NOT NULL, approval_id uuid, provider_ref text, operation_id uuid, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,payment_id) REFERENCES payments(tenant_id,id));
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, guest_id uuid, channel text NOT NULL, provider_conversation_id text NOT NULL, funnel_state text NOT NULL DEFAULT 'NEW_LEAD', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,guest_id) REFERENCES guests(tenant_id,id), UNIQUE(tenant_id,channel,provider_conversation_id), UNIQUE(tenant_id,id));
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, conversation_id uuid NOT NULL, provider_message_id text, direction text NOT NULL CHECK(direction IN ('IN','OUT')), encrypted_body bytea NOT NULL, redacted_summary text, delivery_status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id), UNIQUE(tenant_id,conversation_id,provider_message_id));
CREATE TABLE service_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, booking_id uuid NOT NULL, category text NOT NULL, severity text NOT NULL CHECK(severity IN ('S1','S2','S3','S4')), status text NOT NULL, description text NOT NULL, assigned_team text, due_at timestamptz, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id), UNIQUE(tenant_id,id));
CREATE TABLE incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, booking_id uuid, service_request_id uuid, severity text NOT NULL, reason_code text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id), FOREIGN KEY(tenant_id,service_request_id) REFERENCES service_requests(tenant_id,id));
CREATE TABLE handoffs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, conversation_id uuid NOT NULL, reason text NOT NULL, redacted_summary text NOT NULL, assigned_team text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id));
CREATE TABLE trip_intents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, guest_id uuid NOT NULL, expected_date date NOT NULL, date_precision text NOT NULL CHECK(date_precision IN ('EXACT','WEEK','MONTH')), source_message_id uuid NOT NULL, status text NOT NULL DEFAULT 'ACTIVE', FOREIGN KEY(tenant_id,guest_id) REFERENCES guests(tenant_id,id), UNIQUE(tenant_id,id));
CREATE TABLE followups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, guest_id uuid NOT NULL, trip_intent_id uuid, trigger_at timestamptz NOT NULL, channel text NOT NULL, purpose text NOT NULL CHECK(purpose IN ('SERVICE','MARKETING')), template_id uuid NOT NULL, status text NOT NULL CHECK(status IN ('SCHEDULED','CLAIMED','SENT','CANCELLED','SUPPRESSED','FAILED')), claimed_at timestamptz, sent_at timestamptz, suppression_reason text, FOREIGN KEY(tenant_id,guest_id) REFERENCES guests(tenant_id,id), FOREIGN KEY(tenant_id,trip_intent_id) REFERENCES trip_intents(tenant_id,id));
CREATE INDEX followups_due ON followups(trigger_at) WHERE status='SCHEDULED';
CREATE TABLE benefits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, name text NOT NULL, value_minor bigint NOT NULL CHECK(value_minor>=0), currency char(3) NOT NULL, terms_version text NOT NULL, max_uses integer NOT NULL CHECK(max_uses>0), valid_until timestamptz NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE benefit_redemptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, benefit_id uuid NOT NULL, booking_id uuid NOT NULL, operation_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,benefit_id) REFERENCES benefits(tenant_id,id), FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id), UNIQUE(tenant_id,benefit_id,booking_id));
CREATE TABLE feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, booking_id uuid NOT NULL, score integer NOT NULL CHECK(score BETWEEN 0 AND 10), comment text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id));
CREATE TABLE companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, name text NOT NULL, encrypted_billing_profile bytea, policy_version text NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE company_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, company_id uuid NOT NULL, actor_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('TRAVELER','APPROVER','FINANCE','ADMIN')), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id), UNIQUE(tenant_id,company_id,actor_id));
CREATE TABLE corporate_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, company_id uuid NOT NULL, traveler_guest_id uuid NOT NULL, quote_id uuid NOT NULL, cost_center text NOT NULL, status text NOT NULL CHECK(status IN ('PENDING','APPROVED','REJECTED','EXPIRED')), approved_by uuid, approved_at timestamptz, expires_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id), FOREIGN KEY(tenant_id,traveler_guest_id) REFERENCES guests(tenant_id,id), FOREIGN KEY(tenant_id,quote_id) REFERENCES quotes(tenant_id,id));
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, booking_id uuid NOT NULL, company_id uuid NOT NULL, amount_minor bigint NOT NULL CHECK(amount_minor>=0), currency char(3) NOT NULL, status text NOT NULL, protected_document_ref text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
CREATE TABLE knowledge_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, document_key text NOT NULL, version text NOT NULL, title text NOT NULL, status text NOT NULL CHECK(status IN ('DRAFT','ACTIVE','ARCHIVED')), audience text NOT NULL CHECK(audience IN ('PUBLIC','GUEST','STAFF')), valid_from timestamptz NOT NULL, valid_until timestamptz, body text NOT NULL, UNIQUE(tenant_id,document_key,version), UNIQUE(tenant_id,id));
CREATE TABLE knowledge_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, document_id uuid NOT NULL, chunk_no integer NOT NULL, body text NOT NULL, embedding vector(1536), embedding_model text NOT NULL, embedding_version text NOT NULL, FOREIGN KEY(tenant_id,document_id) REFERENCES knowledge_documents(tenant_id,id), UNIQUE(tenant_id,document_id,chunk_no));
-- 1536 is a design choice; select an actual embedding model and rebuild on dimensional change.
CREATE INDEX knowledge_embedding_hnsw ON knowledge_chunks USING hnsw (embedding vector_cosine_ops);
CREATE TABLE integration_configs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, provider text NOT NULL, agency_external_id text, secret_ref text NOT NULL, capabilities jsonb NOT NULL DEFAULT '{}', verified_at timestamptz, UNIQUE(tenant_id,provider,agency_external_id));
CREATE TABLE webhook_inbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, provider text NOT NULL, transport_dedupe_key text NOT NULL, provider_entity_id text, provider_updated_at timestamptz, encrypted_payload bytea NOT NULL, payload_sha256 text NOT NULL, authenticity text NOT NULL CHECK(authenticity IN ('VERIFIED','UNVERIFIED')), status text NOT NULL CHECK(status IN ('RECEIVED','APPLIED','QUARANTINED','FAILED')), received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,provider,transport_dedupe_key));
CREATE TABLE event_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0, UNIQUE(tenant_id,aggregate_type,aggregate_id,aggregate_version,event_type));
CREATE INDEX outbox_unpublished ON event_outbox(created_at) WHERE published_at IS NULL;
CREATE TABLE consumer_receipts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, consumer_name text NOT NULL, event_id uuid NOT NULL, processed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,consumer_name,event_id));
CREATE TABLE tool_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, actor_id uuid NOT NULL, request_id uuid NOT NULL, conversation_id uuid, tool_name text NOT NULL, result_status text NOT NULL, reason_codes text[] NOT NULL DEFAULT '{}', latency_ms integer NOT NULL CHECK(latency_ms>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE analytics_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, event_type text NOT NULL, entity_id uuid NOT NULL, dedupe_key text NOT NULL, reason_codes text[] NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL, UNIQUE(tenant_id,dedupe_key));
CREATE TABLE referral_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, guest_id uuid NOT NULL, code_hash text NOT NULL, terms_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,guest_id) REFERENCES guests(tenant_id,id), UNIQUE(tenant_id,code_hash));
-- Every tenant-bearing table uses default-deny RLS, including tenants itself.
-- SET LOCAL app.tenant_id within every request/job transaction, from trusted identity.
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='tenant_id' LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',r.table_name);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',r.table_name);
  EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)',r.table_name);
 END LOOP;
END $$;
ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenants FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON tenants USING(id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);
-- Application role: NOSUPERUSER NOBYPASSRLS, not schema owner. RLS isolates tenants,
-- object ownership/guest/company rights still enforced by service authorization.
